import React from "react";
import "./ProductList.scss";

const Product = ({ product }) => {
  if (!product) {
    return <div className="product">Produto não encontrado.</div>;
  }

  // Pega a primeira imagem disponível do produto ou usa uma imagem padrão
  const imageUrl =
    product.items?.[0]?.images?.[0]?.imageUrl || "/no-image.jpg";

  // Função para tratar a compra do produto
  const handleBuy = () => {
    alert(`Você comprou: ${product.productName}`);
  };

  return (
    <div className="product">
      <img src={imageUrl} alt={product.productName} />
      <h3>{product.productName}</h3>
      <p><strong>Título:</strong> {product.productTitle}</p>
      <button className="buy-button" onClick={handleBuy}>QUICK SHOP</button>
    </div>
  );
};

export default Product;
